        grid[i][i] = i

    row_used = [set([i]) for i in range(n)]
    col_used = [set([i]) for i in range(n)]

    # Fill upper triangle first, then lower triangle
    # Because QG3 links (i,j) with (j,i)
    cells = []
    for i in range(n):
        for j in range(i+1, n):
            cells.append((i, j))
            cells.append((j, i))

    call_count = [0]

    def check_qg3_partial():
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if a != -1 and b != -1 and grid[a][b] != -1:
                    if grid[a][b] != i:
                        return False
        return True

    def verify_qg3():
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if grid[a][b] != i:
                    return False
        return True

    def backtrack(idx):
        call_count[0] += 1
        if call_count[0] > max_calls:
            return None  # timeout

        if idx == len(cells):
            if verify_qg3():
                return True
            return False

        r, c = cells[idx]

        for v in range(n):
            if v not in row_used[r] and v not in col_used[c]:
                grid[r][c] = v
                row_used[r].add(v)
                col_used[c].add(v)

                if check_qg3_partial():
