                    if res is None:
                        grid[r][c] = -1
                        row_used[r].discard(v)
                        col_used[c].discard(v)
                        return None

                grid[r][c] = -1
                row_used[r].discard(v)
                col_used[c].discard(v)

        return False

    res = backtrack(0)
    if res is True:
        return [row[:] for row in grid]
    return res  # False or None

