def solve_n_smart(n):
    grid = [[-1]*n for _ in range(n)]
    for i in range(n):
        grid[i][i] = i

    row_used = [set([i]) for i in range(n)]
    col_used = [set([i]) for i in range(n)]

    def set_cell(r, c, v):
        """Set grid[r][c]=v and propagate. Returns False if contradiction."""
        if grid[r][c] == v:
            return True
        if grid[r][c] != -1:
            return False  # already set to different value
        if v in row_used[r] or v in col_used[c]:
            return False

        grid[r][c] = v
        row_used[r].add(v)
        col_used[c].add(v)

        # Propagate QG3: x[x[r][c]][x[c][r]] = r
        # We just set x[r][c]=v. If x[c][r] is known (=w), then x[v][w] must be r
        w = grid[c][r]
        if w != -1:
            if not set_cell(v, w, r):
                return False

