        if w != -1:
            if not set_cell(w, v, c):
                return False

        # Also check: for any (i,j) where x[i][j]=r and x[j][i]=c, we need x[r][c]=i
        # But x[r][c]=v, so we need v=i... this is complex to propagate backwards

        # Check: if x[r][c]=v is now set, check all (i,j) where x[i][j]=r, x[j][i]=c
        # => x[r][c] should be i. But x[r][c]=v, so i must equal v.
        # This means: for all i,j: if x[i][j]=r and x[j][i]=c, then i=v
        # Hard to propagate forward easily.

        return True

    def unset_cell(r, c, old_val=-1):
        v = grid[r][c]
        grid[r][c] = old_val
        if old_val == -1:
            row_used[r].discard(v)
            col_used[c].discard(v)

    def check_all_qg3():
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if a != -1 and b != -1 and grid[a][b] != -1:
                    if grid[a][b] != i:
                        return False
        return True

    def verify_qg3():
        for i in range(n):
            for j in range(n):
                a = grid[i][j]
                b = grid[j][i]
                if grid[a][b] != i:
                    return False
        return True

    # Get unfilled cells
    def get_cells():
        return [(i, j) for i in range(n) for j in range(n) if i != j and grid[i][j] == -1]

    def backtrack():
        cells = get_cells()
        if not cells:
            return verify_qg3()

        # Pick cell with fewest options (MRV heuristic)
        best_cell = None
        best_options = None
        for r, c in cells:
            options = [v for v in range(n) if v not in row_used[r] and v not in col_used[c]]
            if len(options) == 0:
                return False
            if best_options is None or len(options) < len(best_options):
                best_cell = (r, c)
                best_options = options

        r, c = best_cell

        for v in best_options:
            # Save state
            saved = [[grid[i][j] for j in range(n)] for i in range(n)]
            saved_row = [set(s) for s in row_used]
            saved_col = [set(s) for s in col_used]

            if set_cell(r, c, v) and check_all_qg3():
